'use server'

import { revalidatePath } from 'next/cache'
import {
  getNotificationPreference,
  setNotificationPreference,
} from './preferences'

export async function toggleNotificationPreference() {
  // Flip the stored preference.
  setNotificationPreference(!getNotificationPreference())

  // Refresh the current page so the Server Component re-renders with the
  // updated value. revalidatePath is Next.js's recommended way to refresh
  // the current route from within a Server Action — it stays on the same
  // page (no redirect).
  revalidatePath('/')
}

