import { toggleNotificationPreference } from './actions'
import { getNotificationPreference } from './preferences'

export default function Home() {
  const enabled = getNotificationPreference()

  return (
    <main>
      <h1>Settings</h1>
      <p>Notifications are currently {enabled ? 'on' : 'off'}.</p>
      <form action={toggleNotificationPreference}>
        <button type="submit">
          {enabled ? 'Turn notifications off' : 'Turn notifications on'}
        </button>
      </form>
    </main>
  )
}

